import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.CjAa9jTu.js";const u=JSON.parse('{"title":"Preparar la estación de trabajo","description":"","frontmatter":{},"headers":[],"relativePath":"py32f003-getting-started/01_setup.md","filePath":"py32f003-getting-started/01_setup.md"}'),i={name:"py32f003-getting-started/01_setup.md"};function n(l,a,s,c,d,p){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="preparar-la-estacion-de-trabajo" tabindex="-1">Preparar la estación de trabajo <a class="header-anchor" href="#preparar-la-estacion-de-trabajo" aria-label="Permalink to &quot;Preparar la estación de trabajo&quot;">​</a></h1><h2 id="material-basico" tabindex="-1">Material básico <a class="header-anchor" href="#material-basico" aria-label="Permalink to &quot;Material básico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Material</th><th>Uso</th></tr></thead><tbody><tr><td>Placa DevLab PY32F003L24D6TR</td><td>Ejecutar el programa</td></tr><tr><td>Programador CMSIS-DAP/SWD</td><td>Cargar el firmware; por ejemplo, DevLab CH552 con firmware CMSIS-DAP</td></tr><tr><td>Cable USB de datos</td><td>Conectar el programador a la computadora</td></tr><tr><td>Cable JST SH de 1.0 mm, 4 pines, con correspondencia verificada</td><td>Conectar alimentación, GND, SWDIO y SWCLK</td></tr><tr><td>Computadora con Arduino IDE y Python</td><td>Compilar y ejecutar pyOCD</td></tr></tbody></table><p>Para Blink y la práctica de validación basta con este material. El instructor debe preparar previamente el programador en modo <strong>CMSIS-DAP</strong> y verificar el puente <strong>LED Enable</strong>.</p><h2 id="accesorios-para-ampliar-las-practicas" tabindex="-1">Accesorios para ampliar las prácticas <a class="header-anchor" href="#accesorios-para-ampliar-las-practicas" aria-label="Permalink to &quot;Accesorios para ampliar las prácticas&quot;">​</a></h2><ul><li>Pulsador externo, protoboard y cables para la <a href="./../examples/lab02-gpio">entrada digital</a>.</li><li>Adaptador USB-UART con lógica de <strong>3.3 V</strong> para <a href="./../examples/lab03-uart">UART</a>.</li><li>Potenciómetro de 10 kΩ y multímetro para <a href="./../examples/lab04-adc">ADC</a>.</li></ul><h2 id="preparacion-del-software" tabindex="-1">Preparación del software <a class="header-anchor" href="#preparacion-del-software" aria-label="Permalink to &quot;Preparación del software&quot;">​</a></h2><ol><li>Instala <a href="https://www.arduino.cc/en/software/" target="_blank" rel="noreferrer">Arduino IDE</a>.</li><li>Instala Python con acceso desde la terminal.</li><li>Sigue la <a href="./02_0_duino">instalación del paquete PY32 y pyOCD</a>.</li><li>Descarga y extrae el <a href="/unit_devlab_cortex_m_examples/examples/py32f003-ejemplos.zip">paquete de ejemplos</a>.</li><li>Comprueba la compilación de <code>01_blink</code> antes de comenzar la sesión.</li></ol><h2 id="alimentacion-de-referencia" tabindex="-1">Alimentación de referencia <a class="header-anchor" href="#alimentacion-de-referencia" aria-label="Permalink to &quot;Alimentación de referencia&quot;">​</a></h2><p>Con todo desconectado, identifica <strong>5V</strong>, <strong>3V3</strong>, <strong>VCC</strong> y <strong>GND</strong> en el <a href="./03_pinout">pinout</a>. Para estas prácticas, utiliza una estación con <strong>VCC a 3.3 V</strong> y señales compatibles con ese nivel.</p><p>El selector de VCC une el punto central con 3.3 V o con 5 V. Cuando se utiliza la entrada <strong>5V</strong>, el regulador genera <strong>3V3</strong>; el selector debe quedar en 3.3 V para alimentar así al microcontrolador. Un programador que alimente directamente <strong>VCC</strong> debe entregar la tensión acordada para esa estación. El cable de cuatro pines transporta VCC, por lo que hay que comprobar su tensión antes de conectarlo.</p><div class="warning custom-block"><p class="custom-block-title">Alimentación y señales</p><p>No unas dos fuentes de alimentación a VCC. Algunos programadores tienen una salida de alimentación y otros sólo una entrada de referencia VTref: revisa el modelo utilizado. La lógica USB-UART y la entrada ADC se usarán a 3.3 V.</p></div><h2 id="comprobacion-inicial" tabindex="-1">Comprobación inicial <a class="header-anchor" href="#comprobacion-inicial" aria-label="Permalink to &quot;Comprobación inicial&quot;">​</a></h2><ul><li>El programador aparece con <code>pyocd list</code>.</li><li>La selección de placa indica PY32F003x4, 16 KB de Flash y 2 KB de RAM.</li><li>SWDIO, SWCLK, VCC y GND corresponden con las señales de la placa.</li><li>El LED de alimentación enciende y Blink compila.</li></ul><p><strong>Siguiente paso:</strong> <a href="./02_0_duino">Arduino IDE</a>.</p>',15)])])}const b=e(i,[["render",n]]);export{u as __pageData,b as default};
